<?php
require_once dirname(__DIR__).'/includes/auth.php';
require_once dirname(__DIR__).'/includes/ui.php';
$u=require_role('student');
$err='';
$q=db()->prepare('SELECT p.*,pr.name programme_name,d.name department_name,f.name faculty_name,ac.name session_name FROM projects p JOIN project_members pm ON pm.project_id=p.id JOIN programmes pr ON pr.id=p.programme_id JOIN departments d ON d.id=p.department_id JOIN faculties f ON f.id=d.faculty_id JOIN academic_sessions ac ON ac.id=p.academic_session_id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');
$q->execute([$u['id']]);$project=$q->fetch()?:null;

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $action=(string)($_POST['action']??'register');
    if($project&&$action==='revise_idea'){
        $ideaId=filter_var($_POST['idea_id']??null,FILTER_VALIDATE_INT)?:0;
        $title=post_string('title',255);$description=post_string('description',5000);
        $check=db()->prepare("SELECT id FROM project_ideas WHERE id=? AND project_id=? AND submitted_by=? AND review_status='revision_requested'");
        $check->execute([$ideaId,$project['id'],$u['id']]);
        if(!$check->fetchColumn()||mb_strlen($title)<12||mb_strlen($description)<40){$err='The requested idea revision needs a valid title and description.';}
        else{
            db()->prepare("UPDATE project_ideas SET title=?,description=?,review_status='submitted',submitted_at=NOW() WHERE id=?")->execute([$title,$description,$ideaId]);
            $first=db()->prepare('SELECT id FROM project_ideas WHERE project_id=? ORDER BY id LIMIT 1');$first->execute([$project['id']]);if((int)$first->fetchColumn()===$ideaId)db()->prepare('UPDATE projects SET title=?,description=? WHERE id=?')->execute([$title,$description,$project['id']]);
            $supervisor=db()->prepare('SELECT supervisor_id FROM project_supervisors WHERE project_id=? AND ended_at IS NULL');$supervisor->execute([$project['id']]);foreach($supervisor->fetchAll(PDO::FETCH_COLUMN) as $sid)notify_user((int)$sid,'Project idea revised','A student has resubmitted a project idea for your review.','action','project',$project['id']);
            audit('project_idea_resubmitted','project',$project['id'],'Student revised idea '.$ideaId);flash('success','Your revised project idea was sent to your supervisor.');redirect('student/project.php?ideas=1');
        }
    }elseif($project&&$action==='add_idea'){
        $title=post_string('title',255);$description=post_string('description',5000);
        $count=db()->prepare('SELECT COUNT(*) FROM project_ideas WHERE project_id=?');$count->execute([$project['id']]);$ideaCount=(int)$count->fetchColumn();
        $selected=db()->prepare("SELECT COUNT(*) FROM project_ideas WHERE project_id=? AND review_status='approved'");$selected->execute([$project['id']]);
        if($ideaCount>=2||(int)$selected->fetchColumn()>0||mb_strlen($title)<12||mb_strlen($description)<40){$err='A second idea can only be added before an idea is selected, and it needs a valid title and description.';}
        else{db()->prepare('INSERT INTO project_ideas(project_id,submitted_by,title,description,review_status) VALUES(?,?,?, ?,"submitted")')->execute([$project['id'],$u['id'],$title,$description]);db()->prepare('UPDATE projects SET status="idea_under_review" WHERE id=? AND status="idea_rejected"')->execute([$project['id']]);$supervisor=db()->prepare('SELECT supervisor_id FROM project_supervisors WHERE project_id=? AND ended_at IS NULL');$supervisor->execute([$project['id']]);foreach($supervisor->fetchAll(PDO::FETCH_COLUMN) as $sid)notify_user((int)$sid,'Second project idea submitted','A second project idea is ready for your review.','action','project',(int)$project['id']);audit('project_second_idea_submitted','project',(int)$project['id'],'Student added an optional second idea');flash('success','Your second project idea has been submitted for supervisor review.');redirect('student/project.php?ideas=1');}
    }elseif($project){$err='A project is already registered to this account.';}
    else{
        $title1=post_string('idea1_title',255);$description1=post_string('idea1_description',5000);$title2=post_string('idea2_title',255);$description2=post_string('idea2_description',5000);
        $secondStarted=$title2!==''||$description2!=='';
        $department=(int)($u['department_id']??0);$programme=(int)($u['programme_id']??0);$session=(int)db()->query('SELECT id FROM academic_sessions WHERE is_current=1 AND is_closed=0 LIMIT 1')->fetchColumn();
        $programCheck=db()->prepare('SELECT 1 FROM programmes WHERE id=? AND department_id=? AND is_active=1');$programCheck->execute([$programme,$department]);
        if(mb_strlen($title1)<12||mb_strlen($description1)<40||($secondStarted&&(mb_strlen($title2)<12||mb_strlen($description2)<40))||!$department||!$programme||!$session||!$programCheck->fetchColumn()){$err='Enter a valid title and description for Idea 1. If you use Idea 2, complete both its title and description. Confirm your programme and current academic session are configured.';}
        else{
            try{
                db()->beginTransaction();
                $assigned=db()->prepare('SELECT supervisor_id,assigned_by FROM student_supervisors WHERE student_id=? AND ended_at IS NULL ORDER BY assigned_at DESC LIMIT 1');$assigned->execute([$u['id']]);$assignment=$assigned->fetch();
                $ref='NAUB-FYP-'.date('y').'-'.strtoupper(bin2hex(random_bytes(3)));$initialStatus=$assignment?'idea_under_review':'idea_submitted';
                $insert=db()->prepare('INSERT INTO projects(reference_no,title,description,department_id,programme_id,academic_session_id,status) VALUES(?,?,?,?,?,?,?)');$insert->execute([$ref,$title1,$description1,$department,$programme,$session,$initialStatus]);$pid=(int)db()->lastInsertId();
                db()->prepare('INSERT INTO project_members(project_id,student_id) VALUES(?,?)')->execute([$pid,$u['id']]);
                $idea=db()->prepare('INSERT INTO project_ideas(project_id,submitted_by,title,description,review_status) VALUES(?,?,?,?,"submitted")');$idea->execute([$pid,$u['id'],$title1,$description1]);if($secondStarted)$idea->execute([$pid,$u['id'],$title2,$description2]);
                if($assignment)db()->prepare('INSERT INTO project_supervisors(project_id,supervisor_id,assigned_by) VALUES(?,?,?)')->execute([$pid,$assignment['supervisor_id'],$assignment['assigned_by']]);
                foreach(['idea'=>'Project ideas','proposal'=>'Proposal','chapter_1'=>'Chapter 1','chapter_2'=>'Chapter 2','chapter_3'=>'Chapter 3','chapter_4'=>'Chapter 4','chapter_5'=>'Chapter 5','final_submission'=>'Final submission','evaluation'=>'Evaluation','final_approval'=>'Final approval'] as $key=>$label)db()->prepare('INSERT INTO milestones(project_id,milestone_key,label,status) VALUES(?,?,?,?)')->execute([$pid,$key,$label,$key==='idea'?'in_progress':'pending']);
                db()->commit();audit('project_idea_submitted','project',$pid,'Student submitted '.($secondStarted?'two':'one').' project idea(s) '.$ref);
                if($assignment)notify_user((int)$assignment['supervisor_id'],'Project ideas submitted','A student submitted project ideas for your review.','action','project',$pid);
                $coord=db()->query("SELECT id FROM users WHERE role_id=(SELECT id FROM roles WHERE name='coordinator') AND account_status='active'")->fetchAll(PDO::FETCH_COLUMN);foreach($coord as $cid)notify_user((int)$cid,'Project ideas submitted',"{$ref}: supervisor review is pending.",'info','project',$pid);
                flash('success','Your project idea'.($secondStarted?'s were':' was').' submitted. Your assigned supervisor will review and select one.');redirect('student/project.php?ideas=1');
            }catch(Throwable $error){if(db()->inTransaction())db()->rollBack();error_log($error->getMessage());$err='The project ideas could not be saved. Please try again.';}
        }
    }
}

$milestones=[];$projectProgress=0;$assignedSupervisor=null;$recentSubmissions=[];$ideas=[];$ideaSelected=false;
if($project){
    $q=db()->prepare('SELECT * FROM project_ideas WHERE project_id=? ORDER BY id');$q->execute([$project['id']]);$ideas=$q->fetchAll();$ideaSelected=(bool)array_filter($ideas,fn($idea)=>$idea['review_status']==='approved');
    $q=db()->prepare('SELECT * FROM milestones WHERE project_id=? ORDER BY id');$q->execute([$project['id']]);$milestones=$q->fetchAll();
    $docFor=['proposal'=>'proposal','chapter_1'=>'chapter_1','chapter_2'=>'chapter_2','chapter_3'=>'chapter_3','chapter_4'=>'chapter_4','chapter_5'=>'chapter_5','final_submission'=>'final_project'];
    foreach($milestones as &$m){
        if($m['milestone_key']==='idea')$m['status']=$ideaSelected?'completed':($m['status']==='correction_required'?'correction_required':'in_progress');
        if(isset($docFor[$m['milestone_key']])){$q=db()->prepare('SELECT status FROM submissions WHERE project_id=? AND document_type=? ORDER BY submitted_at DESC LIMIT 1');$q->execute([$project['id'],$docFor[$m['milestone_key']]]);$submissionStatus=$q->fetchColumn();if($submissionStatus==='approved'||$submissionStatus==='final')$m['status']='completed';elseif($submissionStatus==='correction_required')$m['status']='correction_required';elseif($submissionStatus)$m['status']='in_progress';}
        if(in_array($m['milestone_key'],['evaluation','final_approval'],true)&&in_array($project['status'],['completed','archived'],true))$m['status']='completed';
    }unset($m);
    $done=count(array_filter($milestones,fn($m)=>in_array($m['status'],['completed','waived'],true)));$projectProgress=count($milestones)?(int)round($done/count($milestones)*100):0;$currentStep=ui_current_milestone($milestones);
    $q=db()->prepare('SELECT CONCAT_WS(" ",su.first_name,su.last_name) name,su.email,su.staff_number,d.name department FROM project_supervisors ps JOIN users su ON su.id=ps.supervisor_id LEFT JOIN departments d ON d.id=su.department_id WHERE ps.project_id=? AND ps.ended_at IS NULL ORDER BY ps.assigned_at DESC LIMIT 1');$q->execute([$project['id']]);$assignedSupervisor=$q->fetch();
    $q=db()->prepare('SELECT s.id,s.document_type,s.status,v.id version_id,v.version_number,v.original_filename,v.uploaded_at FROM submissions s JOIN submission_versions v ON v.submission_id=s.id AND v.version_number=s.current_version WHERE s.project_id=? ORDER BY v.uploaded_at DESC LIMIT 5');$q->execute([$project['id']]);$recentSubmissions=$q->fetchAll();
}
$showIdeas=isset($_GET['ideas']);$pageTitle=$showIdeas||!$project?'Project Ideas':'My Project';$crumbTrail=$showIdeas?['My Project','Project ideas']:($project?['My Project']:['Project ideas']);require dirname(__DIR__).'/includes/header.php';
?>
<p class="page-intro">Register and track your project ideas. You may submit one or two; your assigned supervisor reviews them and selects at most one for your project.</p>
<?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<?php if($project): ?>
<section class="project-banner"><div class="project-banner-top"><?= status_badge($project['status']) ?><span><?= $ideaSelected?'Selected project idea':'Supervisor idea review' ?></span><span class="ms-auto ref-chip"><?= e($project['reference_no']) ?></span></div><h2><?= e($ideaSelected?$project['title']:'Project ideas awaiting selection') ?></h2></section>
<section class="card p-4 mb-3"><div class="section-row"><div><h2 class="section-heading mb-1">Your submitted ideas</h2><p class="text-muted mb-0">The supervisor selects one idea. HOD and Dean screens are for administrative monitoring.</p></div><span class="badge text-bg-secondary"><?= count($ideas) ?> of 2 ideas</span></div>
<div class="row g-3 mt-1"><?php foreach($ideas as $index=>$idea): $selected=$idea['review_status']==='approved'; ?><div class="col-lg-6"><article class="card h-100 p-3 <?= $selected?'border-success':'' ?>"><div class="d-flex justify-content-between gap-2 align-items-start"><h3 class="h6 mb-1">Project Idea <?= $index+1 ?><?= $selected?' · Selected':'' ?></h3><?= status_badge($selected?'approved':$idea['review_status']) ?></div><h4 class="h5 mt-2"><?= e($idea['title']) ?></h4><p class="mb-2"><?= nl2br(e($idea['description'])) ?></p><?php if($idea['reviewer_comment']): ?><div class="alert alert-light border mb-0"><strong>Supervisor feedback</strong><p class="mb-0 mt-1"><?= nl2br(e($idea['reviewer_comment'])) ?></p></div><?php elseif(!$selected): ?><p class="small text-muted mb-0">Awaiting supervisor feedback.</p><?php endif; ?>
<?php if($idea['review_status']==='revision_requested'): ?><form method="post" class="border-top mt-3 pt-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="revise_idea"><input type="hidden" name="idea_id" value="<?= (int)$idea['id'] ?>"><h5 class="h6">Revise this idea</h5><div class="mb-2"><label class="form-label" for="rev-title-<?= (int)$idea['id'] ?>">Updated title</label><input class="form-control" id="rev-title-<?= (int)$idea['id'] ?>" name="title" minlength="12" maxlength="255" value="<?= e($idea['title']) ?>" required></div><div class="mb-2"><label class="form-label" for="rev-description-<?= (int)$idea['id'] ?>">Updated description</label><textarea class="form-control" id="rev-description-<?= (int)$idea['id'] ?>" name="description" rows="4" minlength="40" maxlength="5000" required><?= e($idea['description']) ?></textarea></div><button class="btn btn-primary">Send revised idea</button></form><?php endif; ?></article></div><?php endforeach; ?></div>
<?php if(count($ideas)<2&&!$ideaSelected): ?><form method="post" class="card p-3 mt-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_idea"><h3 class="h6">Add an optional second idea</h3><div class="row g-3"><div class="col-md-5"><label class="form-label" for="idea2-title">Project title</label><input class="form-control" id="idea2-title" name="title" minlength="12" maxlength="255" required></div><div class="col-md-7"><label class="form-label" for="idea2-description">Description and problem statement</label><textarea class="form-control" id="idea2-description" name="description" rows="3" minlength="40" maxlength="5000" required></textarea></div></div><button class="btn btn-outline-primary mt-3 align-self-start">Submit second idea</button></form><?php endif; ?>
</section>
<section class="card p-4 mb-3"><h2 class="section-heading">Project roadmap</h2><?= ui_stepper($milestones) ?></section>
<div class="row g-3"><div class="col-xl-7"><section class="card p-4 h-100"><h2 class="section-heading">Academic information</h2><div class="meta-pair"><div><span class="info-label">Faculty</span><strong><?= e($project['faculty_name']) ?></strong></div><div><span class="info-label">Department</span><strong><?= e($project['department_name']) ?></strong></div><div><span class="info-label">Programme</span><strong><?= e($project['programme_name']) ?></strong></div><div><span class="info-label">Academic session</span><strong><?= e($project['session_name']) ?></strong></div></div><div class="d-flex flex-wrap gap-2 mt-4"><a class="btn btn-primary" href="<?= e(url('student/submissions.php?new=1')) ?>">Submit project work</a><a class="btn btn-outline-primary" href="<?= e(url('student/final-submission.php')) ?>">Final submission</a><a class="btn btn-outline-primary" href="<?= e(url('student/progress.php')) ?>">Full progress</a></div></section></div>
<div class="col-xl-5"><section class="card p-4 h-100"><h2 class="section-heading">Assigned supervisor</h2><?php if($assignedSupervisor): ?><div class="person person-lg"><span class="person-avatar"><?= e(ui_initials($assignedSupervisor['name']?:'S')) ?></span><div><strong><?= e($assignedSupervisor['name']?:'Supervisor') ?></strong><small><?= e($assignedSupervisor['department']?:'Academic supervisor') ?></small><?php if($assignedSupervisor['email']): ?><a class="mail-link" href="mailto:<?= e($assignedSupervisor['email']) ?>"><?= e($assignedSupervisor['email']) ?></a><?php endif; ?></div></div><?php else: ?><div class="empty-state">Your HOD has not assigned a supervisor yet. The ideas will be visible to your department HOD for assignment.</div><?php endif; ?><hr><div class="info-label">Current stage</div><strong><?= e($currentStep['label']??'Project complete') ?></strong><div class="progress mt-2" role="progressbar" aria-label="Project progress" aria-valuenow="<?= $projectProgress ?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?= $projectProgress ?>%"></div></div><small class="text-muted mt-1 d-block"><?= $projectProgress ?>% based on recorded milestones</small></section></div></div>
<section class="card p-4 mt-3"><div class="section-row"><h2 class="section-heading mb-0">Latest submissions</h2><a class="view-link" href="<?= e(url('student/submissions.php')) ?>">Submission history</a></div><div class="table-responsive mt-3"><table class="table table-soft"><thead><tr><th>Document</th><th>File</th><th>Version</th><th>Submitted</th><th>Status</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($recentSubmissions as $r): ?><tr><td class="fw-bold"><?= e(ui_doc_label($r['document_type'])) ?></td><td><?= e($r['original_filename']) ?></td><td>v<?= (int)$r['version_number'] ?></td><td class="text-muted"><?= e(ui_date($r['uploaded_at'])) ?></td><td><?= ui_pill($r['status']) ?></td><td class="text-end"><a class="view-link" href="<?= e(url('student/submission-details.php?version='.(int)$r['version_id'])) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$recentSubmissions): ?><tr><td colspan="6"><div class="empty-state">Your submitted documents will appear here.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?>
<section class="card p-4 register-card"><div class="project-empty-mark" aria-hidden="true"><?= ui_icon('book',24) ?></div><h2 class="section-heading">Register Project Idea</h2><p class="text-muted">Submit one idea or offer a second option for your supervisor to consider. The supervisor makes the academic selection; a similarity score never rejects an idea automatically.</p>
<form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="register"><div class="row g-3"><div class="col-lg-6"><fieldset class="border rounded p-3 h-100"><legend class="float-none w-auto px-2 h6">Project Idea 1 <span class="text-danger">*</span></legend><div class="mb-3"><label class="form-label" for="idea1_title">Proposed title</label><input class="form-control" id="idea1_title" name="idea1_title" minlength="12" maxlength="255" required></div><div><label class="form-label" for="idea1_description">Description and problem statement</label><textarea class="form-control" id="idea1_description" name="idea1_description" rows="6" minlength="40" maxlength="5000" required></textarea></div></fieldset></div><div class="col-lg-6"><fieldset class="border rounded p-3 h-100"><legend class="float-none w-auto px-2 h6">Project Idea 2 <span class="text-muted fw-normal">Optional</span></legend><div class="mb-3"><label class="form-label" for="idea2_title">Proposed title</label><input class="form-control" id="idea2_title" name="idea2_title" minlength="12" maxlength="255"></div><div><label class="form-label" for="idea2_description">Description and problem statement</label><textarea class="form-control" id="idea2_description" name="idea2_description" rows="6" minlength="40" maxlength="5000"></textarea><div class="form-text">If you start Idea 2, complete both fields.</div></div></fieldset></div></div><p class="form-text mt-3">Your faculty, department, programme, and academic session come from your registered student account and cannot be changed on this page.</p><button class="btn btn-primary">Submit project idea</button></form></section>
<?php endif; ?>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
